### 5. Provider-Agnostic SessionApi Interface: `/lib/realtime/types.ts`

**File:** `/Users/jessearmand/Develop/realtime-persona/lib/realtime/types.ts` (75 lines)

**Unified Surface (every provider exposes this):**
```typescript
export interface SessionApi {
  callState: CallState;
  turns: SessionTurn[];
  caption: string;
  muted: boolean;
  elapsed: number;
  isReal: boolean;
  toggleMute: () => void;
  start: () => void;
  hangup: () => void;
  interrupt: () => void;
  getInputVolume: () => number;
  getOutputVolume: () => number;
}

export type CallState = "idle" | "connecting" | "listening" | "speaking" | "interrupted" | "ended";

export interface SessionTurn {
  id: string;
  who: "agent" | "user";
  text: string;
  live?: boolean; // true while agent is still speaking
}
```

**State Helpers:**
```typescript
export const STATE_LABEL: Record<CallState, string> = {
  idle: "IDLE",
  connecting: "CONNECTING",
  listening: "LISTENING",
  speaking: "SPEAKING",
  interrupted: "INTERRUPTED",
  ended: "ENDED",
};

export function isLive(s: CallState): boolean {
  return s !== "idle" && s !== "ended";
}

// CallState → ElevenLabs WebGL Orb agentState
export function toOrbState(s: CallState): AgentState {
  switch (s) {
    case "speaking": return "talking";
    case "listening": case "interrupted": return "listening";
    case "connecting": return "thinking";
    default: return null;
  }
}

// CallState → BarVisualizer state
export function toBarState(s: CallState): BarState {
  switch (s) {
    case "speaking": return "speaking";
    case "connecting": return "connecting";
    case "interrupted": case "listening": return "listening";
    default: return "initializing";
  }
}
```

### 6. Unified Session Dispatcher: `/lib/realtime/use-realtime-session.ts`

**File:** `/Users/jessearmand/Develop/realtime-persona/lib/realtime/use-realtime-session.ts` (309 lines)

**Architecture:**
- All three engine hooks (`useConversation` from @elevenlabs/react, `useXaiSession`, and mock state) are called **unconditionally** (rules of hooks)
- They stay inert until their engine is selected
- Provider selection via `provider.engine` (undefined = mock, "elevenlabs" = ElevenLabs, "xai" = xAI)

**Key Dispatch Pattern:**

```typescript
export function useRealtimeSession({
  provider,
  persona,
}: {
  provider: Provider;
  persona?: Persona;
}): SessionApi {
  const engine = provider.engine;
  const isReal = !!engine;

  // ── ALL THREE ENGINES CALLED UNCONDITIONALLY ──
  const conversation = useConversation({ /* ... */ }); // ElevenLabs hook
  const xai = useXaiSession(engine === "xai", persona); // xAI hook (conditional active param)

  // ── DISPATCH TO ACTIVE ENGINE ──
  const activeCallState: CallState = engine === "xai" ? xai.callState : callState;

  const start = useCallback(() => {
    if (engine === "xai") {
      xai.start(); return;
    }
    if (engine === "elevenlabs") {
      startSession({ agentId, connectionType: "webrtc" } as ...);
      return;
    }
    // Mock: setup timers
  }, [engine, xai, callState, startSession, endSession]);

  const hangup = useCallback(() => {
    if (engine === "xai") {
      xai.stop(); return;
    }
    if (engine === "elevenlabs") {
      endSession(); return;
    }
    // Mock: clear timers
  }, [engine, xai, endSession]);

  const interrupt = useCallback(() => {
    if (engine === "xai") {
      xai.interrupt(); return;
    }
    if (stateRef.current !== "speaking") return;
    if (engine === "elevenlabs") {
      conversation.sendUserActivity(); return;
    }
    // Mock: setCallState timer
  }, [engine, xai, conversation]);

  // Return composite SessionApi pointing to active engine
  return useMemo<SessionApi>(
    () => ({
      callState: activeCallState,
      turns: isXai ? xai.turns : turns,
      caption: isXai ? xai.caption : caption,
      muted,
      elapsed,
      isReal,
      toggleMute,
      start,
      hangup,
      interrupt,
      getInputVolume: isXai ? xai.getInputVolume : getInputVolume,
      getOutputVolume: isXai ? xai.getOutputVolume : getOutputVolume,
    }),
    [/* ... */],
  );
}
```

**Hook Lifecycle Management:**
- When engine changes, cleanup the old engine (call `endSession()` for ElevenLabs, teardown for xAI via its `active` effect)
- Reset state to the new engine's initial state

```typescript
useEffect(() => {
  clearTimers();
  try {
    if (realPhase.current === "active") endSession(); // tear down old ElevenLabs
  } catch {
    // no active session
  }
  realPhase.current = "idle";
  if (isReal) {
    setCallState("idle");
    setTurns([]);
    setCaption("press CALL to begin");
  } else {
    setCallState("listening");
    setTurns(SCRIPT_TURNS);
    setCaption(mockCaption("listening"));
  }
}, [engine]); // react to engine change
```

**xAI Hook Inertness:**
```typescript
const xai = useXaiSession(engine === "xai", persona);
```
The `active` parameter gates the xAI hook:
- When `active === false` (other engine selected), the hook's effect cleans up any live session
- When `active === true` and `start()` is called, the hook bootstraps mic + WS

```typescript
useEffect(() => {
  if (active) return; // inert until active
  if (stateRef.current !== "idle") {
    endedRef.current = true;
    teardown(); // clean up if we switch away mid-call
    setCallState("idle");
    setTurns([]);
    setCaption("press CALL to begin");
  }
}, [active, teardown]);
```

