### 2. Audio Pipeline: `/lib/realtime/xai-audio.ts`

**File:** `/Users/jessearmand/Develop/realtime-persona/lib/realtime/xai-audio.ts` (164 lines)

**Format:** Raw PCM16 little-endian base64
- No codec; xAI exchanges audio as uncompressed 16-bit signed integers
- Sample rate: native browser AudioContext rate (advertised to xAI in `session.update`)
- Capture: Float32 [-1, 1] → PCM16 signed int16 → base64

**Conversion Functions:**

```typescript
// Float32 [-1,1] → PCM16 → base64
export function float32ToPcm16Base64(float32: Float32Array): string {
  const pcm16 = new Int16Array(float32.length);
  for (let i = 0; i < float32.length; i++) {
    const s = Math.max(-1, Math.min(1, float32[i]));
    pcm16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
  }
  return arrayBufferToBase64(pcm16.buffer);
}

// base64 PCM16 → Float32 [-1,1]
export function base64Pcm16ToFloat32(base64: string): Float32Array {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  const pcm16 = new Int16Array(bytes.buffer);
  const float32 = new Float32Array(pcm16.length);
  for (let i = 0; i < pcm16.length; i++) {
    float32[i] = pcm16[i] / (pcm16[i] < 0 ? 0x8000 : 0x7fff);
  }
  return float32;
}
```

**EarlyAudioBuffer Class:**
- Bounded FIFO (default 50 chunks ≈ 5 seconds at 100ms/chunk)
- Captures mic audio BEFORE `session.updated` arrives
- `push(base64)` — add chunks, drop oldest if over capacity
- `drain()` — return all buffered chunks and reset
- Prevents lost early speech during parallel initialization

**PlaybackQueue Class:**
- Manages gap-less playback of streamed PCM16 chunks
- Chain AudioBufferSourceNodes sequentially (no silence between)
- `enqueue(chunk: Float32Array)` — add a chunk; start playback if idle
- `stop()` — kill current source and clear queue (for barge-in)
- `level` property — exposes RMS of currently-playing chunk for orb visualization

**Capture Pipeline (in use-xai-session.ts):**
```typescript
const ctx = new AudioContext();
const rate = ctx.sampleRate; // advertise to xAI
const stream = await navigator.mediaDevices.getUserMedia({
  audio: {
    channelCount: 1,
    echoCancellation: true,
    noiseSuppression: true,
    autoGainControl: true,
  },
});
const source = ctx.createMediaStreamSource(stream);
const proc = ctx.createScriptProcessor(4096, 1, 1); // 1-in, 1-out

proc.onaudioprocess = (e) => {
  const input = e.inputBuffer.getChannelData(0); // Float32
  inputRmsRef.current = calculateRms(input); // for volume display
  if (!muted) {
    // Accumulate frames until we have a 100ms chunk
    pending.push(new Float32Array(input));
    // When 100ms worth is ready, convert to PCM16 base64
    const audio = float32ToPcm16Base64(chunk);
    if (streamingRef.current) {
      send({ type: "input_audio_buffer.append", audio });
    } else {
      earlyBufRef.current?.push(audio);
    }
  }
};

source.connect(proc);
proc.connect(ctx.destination); // required in some browsers for callback to fire
```

### 3. Token Endpoint: `/app/api/xai/token/route.ts`

**File:** `/Users/jessearmand/Develop/realtime-persona/app/api/xai/token/route.ts` (59 lines)

**Purpose:** Mint ephemeral client-secret tokens server-side so the browser never sees `XAI_API_KEY`

**Flow:**
```
Browser POST /api/xai/token
  ↓ (server-side)
Fetch xAI's /v1/realtime/client_secrets with Bearer token (XAI_API_KEY)
  ↓
Return ephemeral token JSON to browser
  ↓ (client-side)
Browser uses token in WebSocket subprotocol: "xai-client-secret.TOKEN"
```

**Implementation:**
```typescript
const CLIENT_SECRETS_URL = "https://api.x.ai/v1/realtime/client_secrets";
const TOKEN_TTL_SECONDS = 300; // 5 minutes

export async function POST(): Promise<Response> {
  const apiKey = process.env.XAI_API_KEY;
  if (!apiKey) {
    return Response.json(
      { error: "XAI_API_KEY is not set on the server (provide it via fnox)." },
      { status: 500 },
    );
  }

  let upstream: Response;
  try {
    upstream = await fetch(CLIENT_SECRETS_URL, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({ expires_after: { seconds: TOKEN_TTL_SECONDS } }),
    });
  } catch (err) {
    return Response.json({ error: `Failed to reach xAI: ...` }, { status: 502 });
  }

  const text = await upstream.text();
  if (!upstream.ok) {
    return Response.json(
      { error: "xAI client_secrets request failed", status: upstream.status, detail: text },
      { status: 502 },
    );
  }

  return new Response(text, {
    status: 200,
    headers: { "Content-Type": "application/json", "Cache-Control": "no-store" },
  });
}
```

**Token Extraction (robust parsing):**
```typescript
function extractToken(data: unknown): string | null {
  if (typeof data !== "object" || data === null) return null;
  const d = data as Record<string, unknown>;
  if (typeof d.value === "string") return d.value;
  if (typeof d.token === "string") return d.token;
  if (typeof d.secret === "string") return d.secret;
  const cs = d.client_secret;
  if (typeof cs === "string") return cs;
  if (cs && typeof cs === "object" && typeof (cs as Record<string, unknown>).value === "string") {
    return (cs as Record<string, unknown>).value as string;
  }
  return null;
}
```

