- Provider selection via `provider.engine` (undefined = mock, "elevenlabs" = ElevenLabs, "xai" = xAI)

**Key Dispatch Pattern:**

```typescript
export function useRealtimeSession({
  provider,
  persona,
}: {
  provider: Provider;
  persona?: Persona;
}): SessionApi {
  const engine = provider.engine;
  const isReal = !!engine;

  // ── ALL THREE ENGINES CALLED UNCONDITIONALLY ──
  const conversation = useConversation({ /* ... */ }); // ElevenLabs hook
  const xai = useXaiSession(engine === "xai", persona); // xAI hook (conditional active param)

  // ── DISPATCH TO ACTIVE ENGINE ──
  const activeCallState: CallState = engine === "xai" ? xai.callState : callState;

  const start = useCallback(() => {
    if (engine === "xai") {
      xai.start(); return;
    }
    if (engine === "elevenlabs") {
      startSession({ agentId, connectionType: "webrtc" } as ...);
      return;
    }
    // Mock: setup timers
  }, [engine, xai, callState, startSession, endSession]);

  const hangup = useCallback(() => {
    if (engine === "xai") {
      xai.stop(); return;
    }
    if (engine === "elevenlabs") {
      endSession(); return;
    }
    // Mock: clear timers
  }, [engine, xai, endSession]);

  const interrupt = useCallback(() => {
    if (engine === "xai") {
      xai.interrupt(); return;
    }
    if (stateRef.current !== "speaking") return;
    if (engine === "elevenlabs") {
      conversation.sendUserActivity(); return;
    }
    // Mock: setCallState timer
  }, [engine, xai, conversation]);

  // Return composite SessionApi pointing to active engine
  return useMemo<SessionApi>(
    () => ({
      callState: activeCallState,
      turns: isXai ? xai.turns : turns,
      caption: isXai ? xai.caption : caption,
      muted,
      elapsed,
      isReal,
      toggleMute,
      start,
      hangup,
      interrupt,
      getInputVolume: isXai ? xai.getInputVolume : getInputVolume,
      getOutputVolume: isXai ? xai.getOutputVolume : getOutputVolume,
    }),
    [/* ... */],
  );
}
```

**Hook Lifecycle Management:**
- When engine changes, cleanup the old engine (call `endSession()` for ElevenLabs, teardown for xAI via its `active` effect)
- Reset state to the new engine's initial state

