### 8. **Audio Pipeline (xAI example; OpenAI will differ)**

**File:** `/Users/jessearmand/Develop/realtime-persona/lib/realtime/xai-audio.ts`

**Mic capture → PCM16 → base64:**
```typescript
export function float32ToPcm16Base64(float32: Float32Array): string {
  const pcm16 = new Int16Array(float32.length);
  for (let i = 0; i < float32.length; i++) {
    const s = Math.max(-1, Math.min(1, float32[i]));
    pcm16[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
  }
  return arrayBufferToBase64(pcm16.buffer);
}
```

**Agent audio (base64 PCM16) → Float32 → playback:**
```typescript
export function base64Pcm16ToFloat32(base64: string): Float32Array {
  const binary = atob(base64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) {
    bytes[i] = binary.charCodeAt(i);
  }
  const pcm16 = new Int16Array(bytes.buffer);
  const float32 = new Float32Array(pcm16.length);
  for (let i = 0; i < pcm16.length; i++) {
    float32[i] = pcm16[i] / (pcm16[i] < 0 ? 0x8000 : 0x7fff);
  }
  return float32;
}
```

**PlaybackQueue** — gap-less playback of streamed chunks via chained `AudioBufferSourceNode`s (implements `level` prop for orb visualization).

