async () => {
  const out = { secure: window.isSecureContext, hasMD: !!navigator.mediaDevices };
  try {
    const s = await navigator.mediaDevices.getUserMedia({ audio: true });
    out.gum = "ok";
    out.tracks = s.getAudioTracks().map((t) => ({ label: t.label, enabled: t.enabled, muted: t.muted }));
    s.getTracks().forEach((t) => t.stop());
  } catch (e) {
    out.gum = "error";
    out.err = String(e && e.name) + ": " + String(e && e.message);
  }
  return out;
}

