async () => {
  await new Promise((r) => setTimeout(r, 8000));
  const o = window.__oai || { sent: [], events: [], errors: [] };
  const sessionUpdate = o.sent.find((m) => m.type === "session.update");
  const counts = {};
  for (const t of o.events) counts[t] = (counts[t] || 0) + 1;
  return {
    sentTurnDetection: sessionUpdate?.session?.audio?.input?.turn_detection,
    sentTranscription: sessionUpdate?.session?.audio?.input?.transcription,
    sentReasoning: sessionUpdate?.session?.reasoning,
    errors: o.errors.map((e) => e.error?.message || e),
    speechStarted: counts["input_audio_buffer.speech_started"] || 0,
    sessionUpdated: counts["session.updated"] || 0,
    transcriptDeltas: counts["response.output_audio_transcript.delta"] || 0,
    caption: document.querySelector(".tb-caption-t")?.textContent?.slice(0, 70),
  };
}

